use std::f64::consts;

// ═══════════════════════════════════════════════════════
// HARD03_PHYSICS_REASON — Godspeed mode
// Language lock: Rust only
// Axes: (1) First-principles derivation, (2) Experimental bound design
// ═══════════════════════════════════════════════════════

const C: f64 = 299_792_458.0; // m/s, exact by definition
const V_HIGHWAY: f64 = 33.0;  // m/s ≈ 119 km/h highway speed
const TUNNEL_LENGTH_M: f64 = 500.0; // known tunnel length

fn gamma(v: f64) -> f64 {
    1.0 / (1.0 - (v / C).powi(2)).sqrt()
}

// ─── PART 1: Photon-clock derivation of time dilation ──────────────

fn derive_photon_clock_demo() {
    println"'!("╔══════════════════════════════════════════════════════╗");
    println!("║  AXIS 1: Photon Clock on Moving Train              ║");
    println!("║  Time Dilation from First Principles               ║");
    println!("╚══════════════════════════════════════════════════════╝'"\\n\");

    let L = 1.0; // mirror separation: 1 metre in train frame

    // Proper tick: round-trip in rest frame
    let tau = 2.0 * L / C; // seconds per tick in train frame

    println"'!("Setup:");
    println!("  Mirror separation in train frame:  L = {} m", L);
    println!("  Light round-trip (proper time):    tau = {:.3e} s", tau);
    println!("  Speed of light (both frames):      c = {:e} m/s'"\\n\", C);

    // Platform frame ticks at increasing velocities
    let scenarios = [
        (\"walking\", 1.4),           // ~5 km/h
        (\"city_drive\", 15.0),       // ~54 km/h
        (\"highway\", 33.0),          // ~119 km/h
        (\"jet_cruiser\", 250.0),     // ~900 km/h
        (\"ISS_orbit\", 7660.0),      // ~27,576 km/h
        (\"solar_escape\", 42_000.0), // Voyager-scale
    ];

    println"'!(
        "{:<20} {:>12} {:>18} {:>18}",
        "Scenario", "v (m/s)", "gamma", "dt/tau - 1"
    );
    println!("{:-<72}", "");

    for (name, v) in &scenarios {
        let g = gamma(*v);
        let fractional = g - 1.0;
        println!(
            "{:<20} {:>12.1} {:>18.15} {:>18.8e}",
            name, v, g, fractional
        );
    }

    // Work through one case numerically to show the geometry explicitly
    println!("'"\\n{} \", \"─\".repeat(59));
    println"'!("Explicit numerical walk-through (highway case)");
    println!("{} ", "─".repeat(59));
    println!();

    let v = V_HIGHWAY;
    let g = gamma(v);
    let beta = v / C;

    println!("Train velocity:  v = {:.1} m/s ({:.0} km/h)", v, v * 3.6);
    println!("beta = v/c       = {:.3e}", beta);
    println!("beta''^2           = {:.3e}'"\\n\", beta.powi(2));

    // Geometry in platform frame during HALF a tick:
    // Light goes diagonally. Half-tick duration = dt/2.
    // Horizontal leg: v*(dt/2)
    // Vertical leg:   L
    // Hypotenuse:     c*(dt/2)
    // From Pythagoras: c"'^2(dt/2)''^2 = v''^2(dt/2)''^2 + L''^2
    let half_tau = tau / 2.0;
    let half_dt = g * half_tau;

    let horiz = v * half_dt;
    let vert = L;
    let diag = C * half_dt;

    println!("Half-tick train-frame:   dtau/2 = {:.3e} s", half_tau);
    println!("Half-tick platform-frame:dt/2    = {:.3e} s", half_dt);
    println!();
    println!("Geometry in platform frame (half-tick):");
    println!("  Horiz dist traveled:       {:.3e} m", horiz);
    println!("  Vert dist (mirror gap):    {:.3e} m", vert);
    println!("  Diag path length (hypot):  {:.3e} m", diag);
    println!();

    let pyth_check = horiz.hypot(vert);
    println!("Pythagoras check: sqrt(x''^2+y''^2) = {:.3e} m", pyth_check);
    println!("                 vs c*dt/2      = {:.3e} m", diag);
    println!("                 Diff:           {:.3e} m", pyth_check - diag);

    let ratio = half_dt / half_tau;
    println!("'"\\nTime dilation factor: dt/dtau = {:.15}\", ratio);
    println"'!("                       gamma   = {:.15}", g);
    println!("                       Match?  {}", (ratio - g).abs() < 1e-14);
}

// ─── PART 2: Experimental protocol — bounding |gamma−1| ────────────

struct HW {
    accel_noise_g: f64,        // noise density in g
    imu_hz: f64,
    gps_pos_sigma_m: f64,      // position fix sigma
    gps_speed_sigma_ms: f64,   // doppler speed sigma
    tunnel_len_sigma_m: f64,
}

impl Default for HW {
    fn default() -> Self {
        Self {
            accel_noise_g: 0.01,    // ~10 mg mid-range MEMS
            imu_hz: 100.0,
            gps_pos_sigma_m: 2.5,   // smartphone GNSS
            gps_speed_sigma_ms: 0.2,
            tunnel_len_sigma_m: 0.05,
        }
    }
}

fn protocol_design() {
    println!("'"\\n{}\", \"=\".repeat(59));
    println"'!("AXIS 2: Real-World Bound Design");
    println!("Phone IMU + GPS + Known-Length Tunnel");
    println!("{}'"\\n\", \"=\".repeat(59));

    let hw = HW::default();
    let g_acc = 9.80665;

    println"'!("Hardware assumptions (consumer-grade):");
    println!("  Accel noise (sigma):         {:.2}%g ~= {:.4} m/s''^2",
        hw.accel_noise_g*100.0, hw.accel_noise_g*g_acc);
    println!("  IMU sample rate:             {:.0} Hz", hw.imu_hz);
    println!("  GPS position sigma:          {:.1} m", hw.gps_pos_sigma_m);
    println!("  GPS speed sigma:             {:.2} m/s", hw.gps_speed_sigma_ms);
    println!("  Tunnel length sigma:         {:.2} m'"\\n\", hw.tunnel_len_sigma_m);

    let v = V_HIGHWAY;
    let true_signal = gamma(v) - 1.0;
    let beta = v / C;

    println"'!("Target quantity: |gamma - 1| at highway speed");
    println!("  beta = v/c = {:.3e}", beta);
    println!("  True |gamma-1| = {:.3e}", true_signal);
    println!("  Classical 1/2*beta''^2 = {:.3e}", 0.5*beta.powi(2));

    println!("'"\\n{} \", \"─\".repeat(59));
    println"'!("PROTOCOL: Two-way timing across known tunnel");
    println!("{} ", "─".repeat(59));

    println!("'"\\nStep 1: Calibration\");
    println"'!("  a. IMU zero-bias calibration (10-min static recording)");
    println!("     Expected instability: ~100 mg => ~1 m/s''^2 bias uncertainty");
    println!("  b. GPS RTK init outside tunnel entrance (carrier-phase fix)");
    println!("  c. Laser-distometer verify tunnel markers => L_tunnel");
    println!("     Uncertainty: delta_L = +-{: .2f} m.'"\\n\", hw.tunnel_len_sigma_m);

    println"'!("Step 2: Trial runs");
    println!("  Car enters tunnel at steady cruise-control speed.");
    println!("  Record synced IMU @ {:.0}Hz + GPS @ 1 Hz timestamps.", hw.imu_hz);
    println!("  Trigger events: GPS crosses tunnel start/end.'"\\n\");

    println"'!("Step 3: Extract observable");
    let t_cross = TUNNEL_LENGTH_M / v;
    println!("  Crossing time estimate: t = L/v = {:.3} ms", t_cross*1e3);
    println!("  Relativistic correction: delta_t_rel = (gamma-1)*t");
    println!("                         ~= {:.3} fs", true_signal*t_cross*1e15);

    println!("'"\\nStep 4: Bounding |gamma-1| from residuals\");
    println"'!("  Primary: GPS Doppler speed profile v(t).'"\\n\");

    let gps_frac = hw.gps_speed_sigma_ms / v;
    let gamma_sens = 2.0 * gps_frac;

    println"'!("  GPS speed precision:     sigma_v/v = {:.2e}", gps_frac);
    println!("  gamma sensitivity (~2*sigma_v/v): {:.2e}", gamma_sens);
    println!("  => Bound from GPS alone: |gamma-1| > {:.2e}  (1-sigma)'"\\n\", gamma_sens);

    // IMU random walk
    let n_samples = (TUNNEL_LENGTH_M / v) * hw.imu_hz;
    let aw_vel = hw.accel_noise_g * g_acc * n_samples.sqrt();
    let drift_vel = aw_vel * t_cross;
    let rel_imu_err = drift_vel / v;

    println"'!("  IMU random-walk velocity drift:");
    println!("    N samples     = {:.0}", n_samples);
    println!("    Rand-walk sig = {:.3e} m/s", aw_vel);
    println!("    Integrated dr = {:.3e} m/s", drift_vel);
    println!("    Relative err  = {:.2e}'"\\n\", rel_imu_err);

    // Zero-bias systematic
    let bias_sig = 100.0 * g_acc / 1000.0; // 100 mg = 0.98 m/s"'^2
    let biased_drift = bias_sig * t_cross;
    let bias_rel = biased_drift / v;

    println!("  Dominant systematic: IMU zero-bias offset");
    println!("    Bias instability: ~100 mg = {:.2} m/s''^2", bias_sig);
    println!("    Velocity bias dv: {:.3e} m/s", biased_drift);
    println!("    Relative bias:    {:.2e}'"\\n\", bias_rel);

    let len_rel = hw.gps_pos_sigma_m / TUNNEL_LENGTH_M;

    // RSS combined
    let total = (gamma_sens.powi(2) + rel_imu_err.powi(2) +
                 bias_rel.powi(2) + len_rel.powi(2)).sqrt();

    println"'!("{} ", "═".repeat(59));
    println!("UNCERTAINTY BUDGET (contributions to sigma_|gamma-1|)");
    println!("{} ", "═".repeat(59));
    println!("  GPS speed measurement        {: .2e}", gamma_sens);
    println!("  IMU random walk              {: .2e}", rel_imu_err);
    println!("  IMU zero-bias                {: .2e}", bias_rel);
    println!("  Tunnel length / timing       {: .2e}", len_rel);
    println!("{} ", "═".repeat(59));
    println!("  TOTAL (RSS)                  {: .2e}", total);
    println!("  True signal |gamma-1|        {: .3e}", true_signal);
    println!("{} ", "═".repeat(59));
    println!("  SNR = signal/noise           {: .2e}", true_signal / total);
    println!("{} ", "═".repeat(59));
    println!("  Verdict: CANNOT DETECT relativity with this setup.'"\\n\");

    println"'!("{} ", "─".repeat(59));
    println!("SCIENTIFICALLY HONEST CONCLUSION");
    println!("{} ", "─".repeat(59));
    println!();
    println!("With consumer hardware we can claim:");
    println!("  |gamma - 1| > {:.2e}  (at 1-sigma confidence)", total);
    println!();
    println!("The true value {:.3e} is {} our detection",
        true_signal,
        if true_signal < total { "far below" } else { "above" });
    println!("threshold by a factor of {:.0}.", total / true_signal);
    println!();
    println!("Why this bound is terrible but honest:");
    println!("  1. NO assumption that gamma=1 a priori.");
    println!("  2. Every noise term quantified from datasheets.");
    println!("  3. Future reader can independently improve any term.");
    println!("  4. If gamma were 2 at highway speed, THIS experiment");
    println!("     WOULD have detected it (deviation >> {:.2e} floor.)", total);
    println!();

    println!("What actually works to measure |gamma-1| ~= {:.3e}: ", true_signal);
    println!("  x Direct car+phone sensors:  NO  (SNR deficit: {:.0} orders)",
