    println!("  v Atomic clock comparison:   YES (Hafele-Keating 1971)");
    println!("  v Muon lifetime dilation:    YES (accelerator physics)");
    println!("  v Mossbauer rotor experiments: YES (Kundig 1963)");
    println!("  v Ives-Stilwell (Doppler):   YES (1938+, modern laser)");
}

